    fseek(f, 0, SEEK_SET);
    char *data = new char[size];
    fread(data, 1, size, f);
    fclose(f);

    QImageIOHandler *handler = new RGBHandler();
    QImage i;
    QBuffer b;
    b.setData(data, size);
    b.open(QIODevice::ReadOnly);
    handler->setDevice(&b);
    handler->canRead();
    handler->read(&i);
    delete handler;
    delete[] data;
    return 0;
}
